export function getAddLaunchPoolBucketV2Instruction<
  TAccountGenesisAccount extends string,
  TAccountBucket extends string,
  TAccountBaseMint extends string,
  TAccountQuoteMint extends string,
  TAccountBucketQuoteTokenAccount extends string,
  TAccountPayer extends string,
  TAccountAuthority extends string,
  TAccountQuoteTokenProgram extends string,
  TAccountAssociatedTokenProgram extends string,
  TAccountSystemProgram extends string,
>(
  input: AddLaunchPoolBucketV2Input<
    TAccountGenesisAccount,
    TAccountBucket,
    TAccountBaseMint,
    TAccountQuoteMint,
    TAccountBucketQuoteTokenAccount,
    TAccountPayer,
    TAccountAuthority,
    TAccountQuoteTokenProgram,
    TAccountAssociatedTokenProgram,
    TAccountSystemProgram
  >
): AddLaunchPoolBucketV2Instruction<
  typeof GENESIS_PROGRAM_PROGRAM_ADDRESS,
  TAccountGenesisAccount,
  TAccountBucket,
  TAccountBaseMint,
  TAccountQuoteMint,
  TAccountBucketQuoteTokenAccount,
  TAccountPayer,
  TAccountAuthority,
  TAccountQuoteTokenProgram,
  TAccountAssociatedTokenProgram,
  TAccountSystemProgram
> {
  // Program address.
  const programAddress = GENESIS_PROGRAM_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    genesisAccount: { value: input.genesisAccount ?? null, isWritable: true },
    bucket: { value: input.bucket ?? null, isWritable: true },
    baseMint: { value: input.baseMint ?? null, isWritable: false },
    quoteMint: { value: input.quoteMint ?? null, isWritable: false },
    bucketQuoteTokenAccount: {
      value: input.bucketQuoteTokenAccount ?? null,
      isWritable: true,
    },
    payer: { value: input.payer ?? null, isWritable: true },
    authority: { value: input.authority ?? null, isWritable: false },
    quoteTokenProgram: {
      value: input.quoteTokenProgram ?? null,
      isWritable: false,
    },
    associatedTokenProgram: {
      value: input.associatedTokenProgram ?? null,
      isWritable: false,
    },
    systemProgram: { value: input.systemProgram ?? null, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedAccount
  >;

  // Original args.
  const args = { ...input };

  // Resolve default values.
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      '11111111111111111111111111111111' as Address<'11111111111111111111111111111111'>;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, 'programId');
  const instruction = {
    accounts: [
      getAccountMeta(accounts.genesisAccount),
      getAccountMeta(accounts.bucket),
      getAccountMeta(accounts.baseMint),
      getAccountMeta(accounts.quoteMint),
      getAccountMeta(accounts.bucketQuoteTokenAccount),
      getAccountMeta(accounts.payer),
      getAccountMeta(accounts.authority),
      getAccountMeta(accounts.quoteTokenProgram),
      getAccountMeta(accounts.associatedTokenProgram),
      getAccountMeta(accounts.systemProgram),
    ],
    programAddress,
    data: getAddLaunchPoolBucketV2InstructionDataEncoder().encode(
      args as AddLaunchPoolBucketV2InstructionDataArgs
    ),
  } as AddLaunchPoolBucketV2Instruction<
    typeof GENESIS_PROGRAM_PROGRAM_ADDRESS,
    TAccountGenesisAccount,
    TAccountBucket,
    TAccountBaseMint,
    TAccountQuoteMint,
    TAccountBucketQuoteTokenAccount,
    TAccountPayer,
    TAccountAuthority,
    TAccountQuoteTokenProgram,
    TAccountAssociatedTokenProgram,
    TAccountSystemProgram
  >;

  return instruction;
}

export type ParsedAddLaunchPoolBucketV2Instruction<
  TProgram extends string = typeof GENESIS_PROGRAM_PROGRAM_ADDRESS,
  TAccountMetas extends readonly IAccountMeta[] = readonly IAccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The address of the genesis account */
    genesisAccount: TAccountMetas[0];
    /** The address of the bucket account */
    bucket: TAccountMetas[1];
    /** The address of the base token mint account */
    baseMint: TAccountMetas[2];
    /** The mint account of the quote token */
    quoteMint: TAccountMetas[3];
    /** The token account owned by the bucket for the quote token */
    bucketQuoteTokenAccount: TAccountMetas[4];
    /** The account paying for the storage fees */
    payer: TAccountMetas[5];
    /** The authority of the genesis account */
    authority?: TAccountMetas[6] | undefined;
    /** The SPL Token program for the quote token */
    quoteTokenProgram: TAccountMetas[7];
    /** The Associated Token program */
    associatedTokenProgram: TAccountMetas[8];
    /** The system program */
    systemProgram: TAccountMetas[9];
  };
  data: AddLaunchPoolBucketV2InstructionData;
};

export function parseAddLaunchPoolBucketV2Instruction<
  TProgram extends string,
  TAccountMetas extends readonly IAccountMeta[],
>(
  instruction: IInstruction<TProgram> &
    IInstructionWithAccounts<TAccountMetas> &
    IInstructionWithData<Uint8Array>
): ParsedAddLaunchPoolBucketV2Instruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    // TODO: Coded error.
    throw new Error('Not enough accounts');
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = instruction.accounts![accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === GENESIS_PROGRAM_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      genesisAccount: getNextAccount(),
      bucket: getNextAccount(),
      baseMint: getNextAccount(),
      quoteMint: getNextAccount(),
      bucketQuoteTokenAccount: getNextAccount(),
      payer: getNextAccount(),
      authority: getNextOptionalAccount(),
      quoteTokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getAddLaunchPoolBucketV2InstructionDataDecoder().decode(
      instruction.data
    ),
  };
}
